uested_surface\":\"calendar.calendar\"}}]",'blocks':blocks,'issues':issues,'syncedAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'source':{'provider':'google-calendar','connection_id':connection_id,'http_status':status_code,'event_count':len(blocks)}}
